def palindromepair(arr, N):
    def is_palindrome(s):
        return s == s[::-1]

    seen = set()

    for word in arr:
        for i in range(len(word) + 1):
            prefix, suffix = word[:i], word[i:]
            if is_palindrome(prefix):
                reversed_suffix = suffix[::-1]
                if reversed_suffix in seen:
                    return True
            if is_palindrome(suffix) and i != len(word):  # Avoid empty suffix being paired with any prefix
                reversed_prefix = prefix[::-1]
                if reversed_prefix in seen:
                    return True
        seen.add(word)

    return False
